cjson = require("cjson")

HttpNetworkManager = {}
local this = HttpNetworkManager;
this.gameServerHost = "";
this.gameServerPost = "";

this.AccountServiceName = "account";
this.LobbyServiceName = "lobby";
this.MatchServiceName = "match";

function HttpNetworkManager.Init()
    HttpNetworkSystem.Instance.onResponseErrorX = function(statusCode)
        if (statusCode == 401) then
            uiSystem:PopDialogX(TextSystem.GetText("server_error"),
                    TextSystem.GetText("server_error_401") .."("..TextSystem.GetText("server_code")..statusCode .. ")",
                    UIManager.DialogOption["Yes"], function(option)
                Debug.LogWarning("========>Change Stage");
                stageSystem.Instance:ChangeStage(StageSystem.Home);
            end);
        else
            uiSystem:PopDialogX(TextSystem.GetText("server_error"),
                    TextSystem.GetText("error_code")..statusCode,
                    UIManager.DialogOption["Yes"], function(option)
            end);
        end
    end
end
--获取大厅服地址
---type:服务器类型 lobby/match 大厅服/匹配服
function HttpNetworkManager.GetServerAddress(serverType, callback)
    local reqCommand = string.format("server/getServer?type=%s", serverType)
    HttpNetworkSystem.Instance:GetServiceRequestX(this.AccountServiceName, reqCommand, HttpNetworkSystem.ExceptionAction.ConfirmRetry, callback);
end
--获取基本信息
function HttpNetworkManager.EnterLobby(uid, callback)
    local msg = {};
    msg.uid = uid;
    local reqCommand = string.format("player/enterLobby");
    HttpNetworkSystem.Instance:PostServiceRequestX(this.LobbyServiceName, reqCommand, cjson.encode(msg), HttpNetworkSystem.ExceptionAction.ConfirmRetry, callback);
end

