    local reqCommand = string.format("user/quickLogin?deviceId=%s", deviceId)
    HttpNetworkSystem.Instance:GetServiceRequestX(this.AccountServiceName, reqCommand, HttpNetworkSystem.ExceptionAction.ConfirmRetry, callback);
end

-- 验证
function HttpNetworkManager.Auth(callback)
    local msg = {};
    msg.deviceId = Global.GetDeviceUID();
    msg.sdkuid = userSystem.Instance.UserInfo.uid;
    msg.token = userSystem.Instance.UserInfo.token;
    msg.channel = Global.GetChannel();
    msg.version = Global.GetClientVersion();
    if userSystem.Instance.UserInfo.isDev then
        msg.isDev = 1;
    else
        msg.isDev = 0;
    end
    local reqCommand = string.format("user/auth");
    HttpNetworkSystem.Instance:PostServiceRequestX(this.AccountServiceName, reqCommand, cjson.encode(msg), HttpNetworkSystem.ExceptionAction.ConfirmRetry, callback);
end

